window.__QR["data/core/20.json"]={"v":[["طه","Ta. Ha"],["مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ","We have not revealed unto thee (Muhammad) this Qur'an that thou shouldst be distressed"],["إِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ","But as a reminder unto him who feareth"],["تَنزِيلٗا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَٰوَٰتِ ٱلۡعُلَى","A revelation from Him Who created the earth and the high heavens"],["ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ","The Beneficent One, Who is established on the Throne"],["لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ","Unto Him belongeth whatsoever is in the heavens and whatsoever is in the earth, and whatsoever is between them, and whatsoever is beneath the sod"],["وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى","And if thou speakest aloud, then lo! He knoweth the secret (thought) and (that which is yet) more hidden"],["ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ","Allah! There is no Allah save Him. His are the most beautiful names"],["وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","Hath there come unto thee the story of Moses"],["إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى","When he saw a fire and said unto his folk: Lo! Wait! I see a fire afar off. Peradventure I may bring you a brand therefrom or may find guidance at the fire"],["فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ","And when he reached it, he was called by name: O Moses"],["إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى","Lo! I, even I, am thy Lord, So take off thy shoes, for lo! thou art in the holy valley of Tuwa"],["وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ","And I have chosen thee, so hearken unto that which is inspired"],["إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ","Lo! I, even I, am Allah, There is no Allah save Me. So serve Me and establish worship for My remembrance"],["إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ","Lo! the Hour is surely coming. But I will to keep it hidden, that every soul may be rewarded for that which it striveth (to achieve)"],["فَلَا يَصُدَّنَّكَ عَنۡهَا مَن لَّا يُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ","Therefor, let not him turn thee aside from (the thought of) it who believeth not therein but followeth his own desire, lest thou perish"],["وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ","And what is that in thy right hand, O Moses"],["قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ","He said: This is my staff whereon I lean, and wherewith I bear down branches for my sheep, and wherein I find other uses"],["قَالَ أَلۡقِهَا يَٰمُوسَىٰ","He said: Cast it down, O Moses"],["فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ","So he cast it down, and lo! it was a serpent, gliding"],["قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ","He said: Grasp it and fear not. We shall return it to its former state"],["وَٱضۡمُمۡ يَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٍ ءَايَةً أُخۡرَىٰ","And thrust thy hand within thine armpit, it will come forth white without hurt. (That will be) another token"],["لِنُرِيَكَ مِنۡ ءَايَٰتِنَا ٱلۡكُبۡرَى","That We may show thee (some) of Our greater portents"],["ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ","Go thou unto Pharaoh! Lo! he hath transgressed (the bounds)"],["قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي","(Moses) said: My Lord! relieve my mind"],["وَيَسِّرۡ لِيٓ أَمۡرِي","And ease my task for me"],["وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي","And loose a knot from my tongue"],["يَفۡقَهُواْ قَوۡلِي","That they may understand my saying"],["وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي","Appoint for me a henchman from my folk"],["هَٰرُونَ أَخِي","Aaron, my brother"],["ٱشۡدُدۡ بِهِۦٓ أَزۡرِي","Confirm my strength with him"],["وَأَشۡرِكۡهُ فِيٓ أَمۡرِي","And let him share my task"],["كَيۡ نُسَبِّحَكَ كَثِيرٗا","That we may glorify Thee much"],["وَنَذۡكُرَكَ كَثِيرًا","And much remember Thee"],["إِنَّكَ كُنتَ بِنَا بَصِيرٗا","Lo! Thou art ever Seeing us"],["قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ","He said: Thou art granted thy request, O Moses"],["وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ","And indeed, another time, already We have shown thee favour"],["إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ","When we inspired in thy mother that which is inspired"],["أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ","Saying: Throw him into the ark, and throw it into the river, then the river shall throw it on to the bank, and there an enemy to Me and an enemy to him shall take him. And I endued thee with love from Me that thou mightest be trained according to My will"],["إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّـٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ","When thy sister went and said: Shall I show you one who will nurse him? and we restored thee to thy mother that her eyes might be refreshed and might not sorrow. And thou didst kill a man and We delivered thee from great distress, and tried thee with a heavy trial. And thou didst tarry years among the folk of Midian. Then camest thou (hither) by (My) providence, O Moses"],["وَٱصۡطَنَعۡتُكَ لِنَفۡسِي","And I have attached thee to Myself"],["ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي","Go, thou and thy brother, with My tokens, and be not faint in remembrance of Me"],["ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ","Go, both of you, unto Pharaoh. Lo! he hath transgressed (the bounds)"],["فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ","And speak unto him a gentle word, that peradventure he may heed or fear"],["قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ","They said: Our Lord! Lo! we fear that he may be beforehand with us or that he may play the tyrant"],["قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ","He said: Fear not. Lo! I am with you twain, Hearing and Seeing"],["فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةٖ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ","So go ye unto him and say: Lo! we are two messengers of thy Lord. So let the children of Israel go with us, and torment them not. We bring thee a token from thy Lord. And peace will be for him who followeth right guidance"],["إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ","Lo! it hath been revealed unto us that the doom will be for him who denieth and turneth away"],["قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ","(Pharaoh) said: Who then is the Lord of you twain, O Moses"],["قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ","He said: Our Lord is He Who gave unto everything its nature, then guided it aright"],["قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ","He said: What then is the state of the generations of old"],["قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبٖۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى","He said: The knowledge thereof is with my Lord in a Record. My Lord neither erreth nor forgetteth"],["ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ","Who hath appointed the earth as a bed and hath threaded roads for you therein and hath sent down water from the sky and thereby We have brought forth divers kinds of vegetation"],["كُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ","(Saying): Eat ye and feed your cattle. Lo! herein verily are portents for men of thought"],["۞مِنۡهَا خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ","Thereof We created you, and thereunto We return you, and thence We bring you forth a second time"],["وَلَقَدۡ أَرَيۡنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ","And We verily did show him all Our tokens, but he denied them and refused"],["قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ","He said: Hast come to drive us out from our land by thy magic, O Moses"],["فَلَنَأۡتِيَنَّكَ بِسِحۡرٖ مِّثۡلِهِۦ فَٱجۡعَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِدٗا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَآ أَنتَ مَكَانٗا سُوٗى","But we surely can produce for thee magic the like thereof; so appoint a tryst between us and you, which neither we nor thou shall fail to keep, at a place convenient (to us both)"],["قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحٗى","(Moses) said: Your tryst shall be the day of the feast, and let the people assemble when the sun hath risen high"],["فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ","Then Pharaoh went and gathered his strength, then came (to the appointed tryst)"],["قَالَ لَهُم مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبٗا فَيُسۡحِتَكُم بِعَذَابٖۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ","Moses said unto them: Woe unto you! Invent not a lie against Allah, lest He extirpate you by some punishment. He who lieth faileth miserably"],["فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ ٱلنَّجۡوَىٰ","Then they debated one with another what they must do, and they kept their counsel secret"],["قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ","They said: Lo! these are two wizards who would drive you out from your country by their magic, and destroy your best traditions"],["فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ","So arrange your plan, and come in battle line. Whoso is uppermost this day will be indeed successful"],["قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ","They said: O Moses! Either throw first, or let us be the first to throw"],["قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ","He said: Nay, do ye throw! Then lo! their cords and their staves, by their magic, appeared to him as though they ran"],["فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ","And Moses conceived a fear in his mind"],["قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ","We said: Fear not! Lo! thou art the higher"],["وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ","Throw that which is in thy right hand! It will eat up that which they have made. Lo! that which they have made is but a wizard's artifice, and a wizard shall not be successful to whatever point (of skill) he may attain"],["فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدٗا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ","Then the wizards were (all) flung down prostrate, crying: We believe in the Lord of Aaron and Moses"],["قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ","(Pharaoh) said: Ye put faith in him before I give you leave. Lo! he is your chief who taught you magic. Now surely I shall cut off your hands and your feet alternately, and I shall crucify you on the trunks of palm trees, and ye shall know for certain which of us hath sterner and more lasting punishment"],["قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ","They said: We choose thee not above the clear proofs that have come unto us, and above Him Who created us. So decree what thou wilt decree. Thou wilt end for us only this life of the world"],["إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ","Lo! we believe in our Lord, that He may forgive us our sins and the magic unto which thou didst force us. Allah is better and more lasting"],["إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ","Lo! whoso cometh guilty unto his Lord, verily for him is hell. There he will neither die nor live"],["وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّـٰلِحَٰتِ فَأُوْلَـٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ","But whoso cometh unto Him a believer, having done good works, for such are the high stations"],["جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ","Gardens of Eden underneath which rivers flow, wherein they will abide for ever. That is the reward of him who groweth"],["وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ","And verily We inspired Moses, saying: Take away My slaves by night and strike for them a dry path in the sea, fearing not to be overtaken, neither being afraid (of the sea)"],["فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ","Then Pharaoh followed them with his hosts and there covered them that which did cover them of the sea"],["وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ","And Pharaoh led his folk astray, he did not guide them"],["يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ","O Children of Israel! We delivered you from your enemy, and we made a covenant with you on the holy mountain's side, and sent down on you the manna and the quails"],["كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ","(Saying): Eat of the good things wherewith We have provided you, and transgress not in respect thereof lest My wrath come upon you: and he on whom My wrath cometh, he is lost indeed"],["وَإِنِّي لَغَفَّارٞ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا ثُمَّ ٱهۡتَدَىٰ","And lo! verily I am Forgiving toward him who repenteth and believeth and doeth good, and afterward walketh aright"],["۞وَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ","And (it was said): What hath made thee hasten from thy folk, O Moses"],["قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ","He said: They are close upon my track. I hastened unto Thee, my Lord, that Thou mightest be well pleased"],["قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِيُّ","He said: Lo! We have tried thy folk in thine absence, and As-Samiri hath misled them"],["فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ قَالَ يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبٞ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِي","Then Moses went back unto his folk, angry and sad. He said: O my people! Hath not your Lord promised you a fair promise? Did the time appointed then appear too long for you, or did ye wish that wrath from your Lord should come upon you, that ye broke tryst with me"],["قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارٗا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ","They said: We broke not tryst with thee of our own will, but we were laden with burdens of ornaments of the folk, then cast them (in the fire), for thus As-Samiri proposed"],["فَأَخۡرَجَ لَهُمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٞ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ","Then he produced for them a calf, of saffron hue, which gave forth a lowing sound. And they cried: This is your god and the god of Moses, but he hath forgotten"],["أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا","See they not, then, that it returneth no saying unto them and possesseth for them neither hurt nor use"],["وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ أَمۡرِي","And Aaron indeed had told them beforehand: O my people! Ye are but being seduced therewith, for lo! your Lord is the Beneficent, so follow me and obey my order"],["قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ","They said: We shall by no means cease to be its votaries till Moses return unto us"],["قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ","He (Moses) said: O Aaron! What held thee back when thou didst see them gone astray"],["أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي","That thou followedst me not? Hast thou then disobeyed my order"],["قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي","He said: O son of my mother! Clutch not my beard nor my head! I feared lest thou shouldst say: Thou hast caused division among the Children of Israel, and hast not waited for my word"],["قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ","(Moses) said: And what hast thou to say, O Samiri"],["قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةٗ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي","He said: I perceived what they perceive not, so I seized a handful from the footsteps of the messenger, and then threw it in. Thus my soul commended to me"],["قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدٗا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا","(Moses) said: Then go! and lo! in this life it is for thee to say: Touch me not! and lo! there is for thee a tryst thou canst not break. Now look upon thy god of which thou hast remained a votary. Verily we will burn it and will scatter its dust over the sea"],["إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمٗا","Your Allah is only Allah, than Whom there is no other Allah. He embraceth all things in His knowledge"],["كَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرٗا","Thus relate We unto thee (Muhammad) some tidings of that which happened of old, and We have given thee from Our presence a reminder"],["مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ يَحۡمِلُ يَوۡمَ ٱلۡقِيَٰمَةِ وِزۡرًا","Whoso turneth away from it, he verily will bear a burden on the Day of Resurrection"],["خَٰلِدِينَ فِيهِۖ وَسَآءَ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ حِمۡلٗا","Abiding under it - an evil burden for them on the Day of Resurrection"],["يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ زُرۡقٗا","The day when the Trumpet is blown. On that day we assemble the guilty white-eyed (with terror)"],["يَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرٗا","Murmuring among themselves: Ye have tarried but ten (days)"],["نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمٗا","We are Best Aware of what they utter when their best in conduct say: Ye have tarried but a day"],["وَيَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ يَنسِفُهَا رَبِّي نَسۡفٗا","They will ask thee of the mountains (on that day). Say: My Lord will break them into scattered dust"],["فَيَذَرُهَا قَاعٗا صَفۡصَفٗا","And leave it as an empty plain"],["لَّا تَرَىٰ فِيهَا عِوَجٗا وَلَآ أَمۡتٗا","Wherein thou seest neither curve nor ruggedness"],["يَوۡمَئِذٖ يَتَّبِعُونَ ٱلدَّاعِيَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسٗا","On that day they follow the summoner who deceiveth not, and voices are hushed for the Beneficent, and thou hearest but a faint murmur"],["يَوۡمَئِذٖ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلٗا","On that day no intercession availeth save (that of) him unto whom the Beneficent hath given leave and whose word He accepteth"],["يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِهِۦ عِلۡمٗا","He knoweth (all) that is before them and (all) that is behind them, while they cannot compass it in knowledge"],["۞وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمٗا","And faces humble themselves before the Living, the Eternal. And he who beareth (a burden of) wrongdoing is indeed a failure (on that day)"],["وَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا يَخَافُ ظُلۡمٗا وَلَا هَضۡمٗا","And he who hath done some good works, being a believer, he feareth not injustice nor begrudging (of his wage)"],["وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا","Thus we have revealed it as a Lecture in Arabic, and have displayed therein certain threats, that peradventure they may keep from evil or that it may cause them to take heed"],["فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا","Then exalted be Allah, the True King! And hasten not (O Muhammad) with the Qur'an ere its revelation hath been perfected unto thee, and say: My Lord! Increase me in knowledge"],["وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا","And verily We made a covenant of old with Adam, but he forgot, and We found no constancy in him"],["وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ","And when We said unto the angels: Fall prostrate before Adam, they fell prostrate (all) save Iblis; he refused"],["فَقُلۡنَا يَـٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ","Therefor we said: O Adam! This is an enemy unto thee and unto thy wife, so let him not drive you both out of the Garden so that thou come to toil"],["إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ","It is (vouchsafed) unto thee that thou hungerest not therein nor art naked"],["وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ","And that thou thirstest not therein nor art exposed to the sun's heat"],["فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَـٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ","But the devil whispered to him, saying: O Adam! Shall I show thee the tree of immortality and power that wasteth not away"],["فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ","Then they twain ate thereof, so that their shame became apparent unto them, and they began to hide by heaping on themselves some of the leaves of the Garden. And Adam disobeyed his Lord, so went astray"],["ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ","Then his Lord chose him, and relented toward him, and guided him"],["قَالَ ٱهۡبِطَا مِنۡهَا جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ","He said: Go down hence, both of you, one of you a foe unto the other. But when there come unto you from Me a guidance, then whoso followeth My guidance, he will not go astray nor come to grief"],["وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ","But he who turneth away from remembrance of Me, his will be a narrow life, and I shall bring him blind to the assembly on the Day of Resurrection"],["قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرٗا","He will say: My Lord! Wherefor hast Thou gathered me (hither) blind, when I was wont to see"],["قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ","He will say: So (it must be). Our revelations came unto thee but thou didst forget them. In like manner thou art forgotten this Day"],["وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ","Thus do We reward him who is prodigal and believeth not the revelations of his Lord; and verily the doom of the Hereafter will be sterner and more lasting"],["أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ","Is it not a guidance for them (to know) how many a generation We destroyed before them, amid whose dwellings they walk? Lo! therein verily are signs for men of thought"],["وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامٗا وَأَجَلٞ مُّسَمّٗى","And but for a decree that had already gone forth from thy Lord, and a term already fixed, the judgment would have been inevitable (in this world)"],["فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ","Therefor (O Muhammad), bear with what they say, and celebrate the praise of thy Lord ere the rising of the sun and ere the going down thereof. And glorify Him some hours of the night and at the two ends of the day, that thou mayst find acceptance"],["وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ","And strain not thine eyes toward that which We cause some wedded pairs among them to enjoy, the flower of the life of the world, that We may try them thereby. The provision of thy Lord is better and more lasting"],["وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ","And enjoin upon thy people worship, and be constant therein. We ask not of thee a provision: We provided for thee. And the sequel is for righteousness"],["وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةٖ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ","And they say: If only he would bring us a miracle from his Lord! Hath there not come unto them the proof of what is in the former scriptures"],["وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابٖ مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ","And if we had destroyed them with some punishment before it, they would assuredly have said: Our Lord! If only Thou hadst sent unto us a messenger, so that we might have followed Thy revelations before we were (thus) humbled and disgraced"],["قُلۡ كُلّٞ مُّتَرَبِّصٞ فَتَرَبَّصُواْۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ","Say: Each is awaiting; so await ye! Ye will come to know who are the owners of the path of equity, and who is right"]],"jal":[[1,1,"سُورَة طَه [ مَكِّيَّة إلّا آيَتَيْ ١٢٠ و١٢١ فَمَدَنِيَّتانِ وآياتها ١٣٥ أوْ أرْبَعُونَ أوْ اثْنَتانِ نَزَلَتْ بَعْد مَرْيَم ]\n\n﴿طَه﴾ اللَّه أعْلَم بِمُرادِهِ بِذَلِكَ"],[2,2,"﴿ما أنْزَلْنا عَلَيْك القُرْآن﴾ يا مُحَمَّد ﴿لِتَشْقى﴾ لِتَتْعَب بِما فَعَلْت بَعْد نُزُوله مِن طُول قِيامك بِصَلاةِ اللَّيْل أيْ خَفِّفْ عَنْ نَفْسك"],[3,3,"﴿إلّا﴾ لَكِنْ أنْزَلْناهُ ﴿تَذْكِرَة﴾ بِهِ ﴿لِمَن يَخْشى﴾ يَخاف اللَّه"],[4,4,"﴿تَنْزِيلًا﴾ بَدَل مِن اللَّفْظ بِفِعْلِهِ النّاصِب لَهُ ﴿مِمَّنْ خَلَقَ الأَرْض والسَّمَوات العُلى﴾ جَمْع عُلْيا كَكُبْرى وكُبَر"],[5,5,"هُوَ ﴿الرَّحْمَن عَلى العَرْش﴾ وهُوَ فِي اللُّغَة سَرِير المُلْك ﴿اسْتَوى﴾ اسْتِواء يَلِيق بِهِ"],[6,6,"﴿لَهُ ما فِي السَّماوات وما فِي الأَرْض وما بَيْنهما﴾ مِن المَخْلُوقات ﴿وما تَحْت الثَّرى﴾ هُوَ التُّراب النَّدِيّ والمُراد الأَرَضُونَ السَّبْع لِأَنَّها تَحْته"],[7,7,"﴿وإنْ تَجْهَر بِالقَوْلِ﴾ فِي ذِكْر أوْ دُعاء فاللَّه غَنِيّ عَنْ الجَهْر بِهِ ﴿فَإنَّهُ يَعْلَم السِّرّ وأَخْفى﴾ مِنهُ: أيْ ما حَدَّثْت بِهِ النَّفْس وما خَطَرَ ولَمْ تُحَدِّث بِهِ فَلا تُجْهِد نَفْسك بِالجَهْرِ"],[8,8,"﴿اللَّه لا إلَه إلّا هُوَ لَهُ الأَسْماء الحُسْنى﴾ التِّسْعَة والتِّسْعُونَ الوارِد بِها الحَدِيث والحُسْنى مُؤَنَّث الأَحْسَن"],[9,9,"﴿وهَلْ﴾ قَدْ"],[10,10,"﴿إذْ رَأى نارًا فَقالَ لِأَهْلِهِ﴾ لِامْرَأَتِهِ ﴿اُمْكُثُوا﴾ هُنا وذَلِكَ فِي مَسِيره مِن مَدَيْنَ طالِبًا مِصْر ﴿إنِّي آنَسْت﴾ أبْصَرْت ﴿نارًا لَعَلِّي آتِيكُمْ مِنها بِقَبَسٍ﴾ بِشُعْلَةٍ فِي رَأْس فَتِيلَة أوْ عُود وقالَ لَعَلَّ لِعَدَمِ الجَزْم بِوَفاءِ الوَعْد. ﴿أوْ أجِد عَلى النّار هُدًى﴾ أيْ هادِيًا يَدُلّنِي عَلى الطَّرِيق وكانَ أخْطَأَها لِظُلْمَةِ اللَّيْل."],[11,11,"﴿فَلَمّا أتاها﴾ وهِيَ شَجَرَة عَوْسَج"],[12,12,"﴿إنِّي﴾ بِكَسْرِ الهَمْزَة بِتَأْوِيلِ نُودِيَ بِقِيلَ وبِفَتْحِها بِتَقْدِيرِ الباء ﴿أنا﴾ تَأْكِيد لِياءِ المُتَكَلِّم ﴿رَبّك فاخْلَعْ نَعْلَيْك إنّك بِالوادِي المُقَدَّس﴾ المُطَهَّر أوْ المُبارَك ﴿طُوًى﴾ بَدَل أوْ عَطْف بَيان بِالتَّنْوِينِ وتَرْكه مَصْرُوف بِاعْتِبارِ المَكان وغَيْر مَصْرُوف لِلتَّأْنِيثِ بِاعْتِبارِ البُقْعَة مَعَ العِلْمِيَّة"],[13,13,"﴿وأَنا اخْتَرْتُك﴾ مِن قَوْمك ﴿فاسْتَمِعْ لِما يُوحى﴾ إلَيْك مِنِّي"],[14,14,"﴿إنّنِي أنا اللَّه لا إلَه إلّا أنا فاعْبُدْنِي وأَقِمْ الصَّلاة لِذِكْرِي﴾ لِذِكْرِي فِيها"],[15,15,"﴿إنّ السّاعَة آتِيَة أكاد أُخْفِيها﴾ عَنْ النّاس ويَظْهَر لَهُمْ قُرْبها بِعَلاماتِها ﴿لِتُجْزى﴾ فِيها ﴿كُلّ نَفْس بِما تَسْعى﴾ بِهِ مِن خَيْر أوْ شَرّ"],[16,16,"﴿فَلا يَصُدَّنَّك﴾ يَصْرِفَنَّك ﴿عَنْها﴾ أيْ عَنْ الإيمان بِها ﴿مَن لا يُؤْمِن بِها واتَّبَعَ هَواهُ﴾ فِي إنْكارها ﴿فَتَرْدى﴾ أيْ فَتَهْلِك إنْ صَدَدْت عَنْها"],[17,17,"﴿وما تِلْكَ﴾ كائِنَة الِاسْتِفْهام لِلتَّقْرِيرِ لِيُرَتِّب عَلَيْهِ المُعْجِزَة فِيها"],[18,18,"﴿قالَ هِيَ عَصايَ أتَوَكَّأ﴾ أعْتَمِد ﴿عَلَيْها﴾ عِنْد الوُثُوب والمَشْي ﴿وأَهُشّ﴾ أخْبِط ورَق الشَّجَر ﴿بِها﴾ لِيَسْقُط ﴿عَلى غَنَمِي﴾ فَتَأْكُلهُ ﴿ولِيَ فِيها مَآرِب﴾ جَمْع مَأْرُبَة مُثَلَّث الرّاء أيْ حَوائِج ﴿أُخْرى﴾ كَحَمْلِ الزّاد والسِّقاء وطَرْد الهَوامّ زادَ فِي الجَواب بَيان حاجاته بِها"],[20,20,"﴿فَأَلْقاها فَإذا هِيَ حَيَّة﴾ ثُعْبان عَظِيم ﴿تَسْعى﴾ تَمْشِي عَلى بَطْنها سَرِيعًا كَسُرْعَةِ الثُّعْبان الصَّغِير المُسَمّى بِالجانِّ المُعَبَّر بِهِ فِيها فِي آيَة أُخْرى"],[21,21,"﴿قالَ خُذْها ولا تَخَفْ﴾ مِنها ﴿سَنُعِيدُها سِيرَتها﴾ مَنصُوب بِنَزْعِ الخافِض أيْ إلى حالَتها ﴿الأُولى﴾ فَأَدْخَلَ يَده فِي فَمها فَعادَتْ عَصًا فَتَبَيَّنَ أنَّ مَوْضِع الإدْخال مَوْضِع مَسْكها بَيْن شُعْبَتَيْها وأُرِيَ ذَلِكَ السَّيِّد مُوسى لِئَلّا يَجْزَع إذا انْقَلَبَتْ حَيَّة لَدى فِرْعَوْن"],[22,22,"﴿واضْمُمْ يَدك﴾ اليُمْنى بِمَعْنى الكَفّ ﴿إلى جَناحك﴾ أيْ جَنْبك الأَيْسَر تَحْت العَضُد إلى الإبِط وأَخْرِجْها ﴿تَخْرُج﴾ خِلاف ما كانَتْ عَلَيْهِ مِن الأَدَمَة ﴿بَيْضاء مِن غَيْر سُوء﴾ أيْ بَرَص تُضِيء كَشُعاعِ الشَّمْس تَغْشى البَصَر ﴿آيَة أُخْرى﴾ وهِيَ بَيْضاء حالانِ مِن ضَمِير تَخْرُج"],[23,23,"﴿لِنُرِيَك﴾ بِها إذا فَعَلْت ذَلِكَ لِإظْهارِها ﴿مِن آياتنا﴾ الآيَة ﴿الكُبْرى﴾ أيْ العُظْمى عَلى رِسالَتك وإذا أرادَ عَوْدها إلى حالَتها الأُولى ضَمَّها إلى جَناحه كَما تَقَدَّمَ وأَخْرَجَها"],[24,24,"﴿اذْهَبْ﴾ رَسُولًا ﴿إلى فِرْعَوْن﴾ ومَن مَعَهُ ﴿إنّهُ طَغى﴾ جاوَزَ الحَدّ فِي كُفْره إلى ادِّعاء الإلَهِيَّة"],[25,25,"﴿قالَ رَبّ اشْرَحْ لِي صَدْرِي﴾ وسِّعْهُ لِتَحَمُّلِ الرِّسالَة"],[26,26,"﴿ويَسِّرْ﴾ سَهِّلْ ﴿لِي أمْرِي﴾ لِأُبَلِّغها"],[27,27,"﴿واحْلُلْ عُقْدَة مِن لِسانِي﴾ حَدَثَتْ مِن احْتِراقه بِجَمْرَةٍ وضَعَها بِفِيهِ وهُوَ صَغِير"],[28,28,"﴿يَفْقَهُوا﴾ يَفْهَمُوا ﴿قَوْلِي﴾ عِنْد تَبْلِيغ الرِّسالَة"],[29,29,"﴿واجْعَلْ لِي وزِيرًا﴾ مُعِينًا عَلَيْها"],[30,30,"﴿هارُون﴾ مَفْعُول ثانٍ ﴿أخِي﴾ عَطْف بَيان"],[31,31,"﴿اُشْدُدْ بِهِ أزْرِي﴾ والفِعْلانِ بِصِيغَتِي الأَمْر والمُضارِع المَجْزُوم وهُوَ جَواب الطَّلَب"],[32,32,"﴿وأَشْرِكْهُ فِي أمْرِي﴾ أيْ الرِّسالَة والفِعْلانِ بِصِيغَتِي الأَمْر والمُضارِع المَجْزُوم وهُوَ جَواب الطَّلَب"],[33,33,"﴿كَيْ نُسَبِّحك﴾ تَسْبِيحًا"],[34,34,"﴿ونَذْكُرك﴾ ذِكْرًا"],[35,35,"﴿إنّك كُنْت بِنا بَصِيرًا﴾ عالِمًا فَأَنْعَمْت بِالرِّسالَةِ"],[36,36,"﴿قالَ قَدْ أُوتِيت سُؤْلك يا مُوسى﴾ مِنّا عَلَيْك"],[38,38,"﴿إذْ﴾ لِلتَّعْلِيلِ ﴿أوْحَيْنا إلى أُمّك﴾ مَنامًا أوْ إلْهامًا لَمّا ولَدَتْك وخافَتْ أنْ يَقْتُلك فِرْعَوْن فِي جُمْلَة مَن يُولَد ﴿ما يُوحى﴾ فِي أمْرك ويُبْدَل مِنهُ"],[39,39,"﴿أنْ اقْذِفِيهِ﴾ ألْقِيهِ ﴿فِي التّابُوت فاقْذِفِيهِ﴾ بِالتّابُوتِ ﴿فِي اليَمّ﴾ بَحْر النِّيل ﴿فَلْيُلْقِهِ اليَمّ بِالسّاحِلِ﴾ أيْ شاطِئِهِ والأَمْر بِمَعْنى الخَبَر ﴿يَأْخُذهُ عَدُوّ لِي وعَدُوّ لَهُ﴾ وهُوَ فِرْعَوْن ﴿وأَلْقَيْت﴾ بَعْد أنْ أخَذَك ﴿عَلَيْك مَحَبَّة مِنِّي﴾ لِتُحَبّ فِي النّاس فَأَحَبَّك فِرْعَوْن وكُلّ مَن رَآك ﴿ولِتُصْنَع عَلى عَيْنِي﴾ تُرَبّى عَلى رِعايَتِي وحِفْظِي لَك"],[40,40,"﴿إذْ﴾ لِلتَّعْلِيلِ ﴿تَمْشِي أُخْتك﴾ مَرْيَم لِتَتَعَرَّف مِن خَبَرك وقَدْ أحْضَرُوا مَراضِع وأَنْتَ لا تَقْبَل ثَدْي واحِدَة مِنهُنَّ ﴿فَتَقُول هَلْ أدُلّكُمْ عَلى مَن يَكْفُلهُ﴾ فَأُجِيبَتْ فَجاءَتْ بِأُمِّهِ فَقَبِلَ ثَدْيها ﴿فَرَجَعْناك إلى أُمّك كَيْ تَقَرّ عَيْنها﴾ بِلِقائِك ﴿ولا تَحْزَن﴾ حِينَئِذٍ ﴿وقَتَلْت نَفْسًا﴾ هُوَ القِبْطِيّ بِمِصْرَ فاغْتَمَمْت لِقَتْلِهِ مِن جِهَة فِرْعَوْن ﴿فَنَجَّيْناك مِن الغَمّ وفَتَنّاك فُتُونًا﴾ اخْتَبَرْناك بِالإيقاعِ فِي غَيْر ذَلِكَ وخَلَّصْناك مِنهُ ﴿فَلَبِثْت سِنِينَ﴾ عَشْرًا ﴿فِي أهْل مَدَيْنَ﴾ بَعْد مَجِيئِك إلَيْها مِن مِصْر عِنْد شُعَيْب النَّبِيّ وتَزَوُّجك بِابْنَتِهِ ﴿ثُمَّ جِئْت عَلى قَدَر﴾ فِي عِلْمِي بِالرِّسالَةِ وهُوَ أرْبَعُونَ سَنَة مِن عُمُرك"],[41,41,"﴿واصْطَنَعْتُك﴾ اخْتَرْتُك ﴿لِنَفْسِي﴾ بِالرِّسالَةِ"],[42,42,"﴿اذْهَبْ أنْتَ وأَخُوك﴾ إلى النّاس ﴿بِآياتِي﴾ التِّسْع ﴿ولا تَنِيا﴾ تَفْتُرا ﴿فِي ذِكْرِي﴾ بِتَسْبِيحٍ وغَيْره"],[43,43,"﴿اذْهَبا إلى فِرْعَوْن إنّهُ طَغى﴾ بِادِّعائِهِ الرُّبُوبِيَّة"],[44,44,"﴿فَقُولا لَهُ قَوْلًا لَيِّنًا﴾ فِي رُجُوعه عَنْ ذَلِكَ ﴿لَعَلَّهُ يَتَذَكَّر﴾ يَتَّعِظ والتَّرَجِّي بِالنِّسْبَةِ إلَيْهِما لِعِلْمِهِ تَعالى بِأَنَّهُ لا يَرْجِع ﴿أوْ يَخْشى﴾ اللَّه فَيَرْجِع"],[45,45,"﴿قالا رَبّنا إنّنا نَخاف أنْ يَفْرُط عَلَيْنا﴾ أيْ يَعْجَل بِالعُقُوبَةِ ﴿أوْ أنْ يَطْغى﴾ عَلَيْنا أيْ يَتَكَبَّر"],[46,46,"﴿قالَ لا تَخافا إنّنِي مَعَكُما﴾ بِعَوْنِي ﴿أسْمَع﴾ ما يَقُول ﴿وأَرى﴾ ما يَفْعَل"],[47,47,"﴿فَأْتِياهُ فَقُولا إنّا رَسُولا رَبّك فَأَرْسِلْ مَعَنا بَنِي إسْرائِيل﴾ إلى الشّام ﴿ولا تُعَذِّبهُمْ﴾ أيْ خَلِّ عَنْهُمْ مِن اسْتِعْمالك إيّاهُمْ فِي. أشْغالك الشّاقَّة كالحَفْرِ والبِناء وحَمْل الثَّقِيل ﴿قَدْ جِئْناك بِآيَةٍ﴾ بِحُجَّةٍ ﴿مِن رَبّك﴾ عَلى صِدْقنا بِالرِّسالَةِ ﴿والسَّلام عَلى مَن اتَّبَعَ الهُدى﴾ أيْ السَّلامَة لَهُ مِن العَذاب"],[48,48,"﴿إنّا قَدْ أُوحِيَ إلَيْنا أنَّ العَذاب عَلى مَن كَذَّبَ﴾ ما جِئْنا بِهِ ﴿وتَوَلّى﴾ أعْرَضَ عَنْهُ فَأَتَياهُ وقالا جَمِيع ما ذُكِرَ"],[49,49,"﴿قالَ فَمَن رَبّكُما يا مُوسى﴾ اقْتَصَرَ عَلَيْهِ لِأَنَّهُ الأَصْل ولِإدْلالِهِ عَلَيْهِ بِالتَّرْبِيَةِ"],[50,50,"﴿قالَ رَبّنا الَّذِي أعْطى كُلّ شَيْء﴾ مِن الخَلْق ﴿خَلْقه﴾ الَّذِي هُوَ عَلَيْهِ مُتَمَيِّز بِهِ عَنْ غَيْره ﴿ثُمَّ هَدى﴾ الحَيَوان مِنهُ إلى مَطْعَمه ومَشْرَبه ومَنكَحِهِ وغَيْر ذَلِكَ"],[51,51,"﴿قالَ﴾ فِرْعَوْن ﴿فَما بال﴾ حال ﴿القُرُون﴾ الأُمَم ﴿الأُولى﴾ كَقَوْمِ نُوح وهُود ولُوط وصالِح فِي عِبادَتهمْ الأَوْثان"],[52,52,"﴿قالَ﴾ مُوسى ﴿عِلْمها﴾ أيْ عِلْم حالهمْ مَحْفُوظ ﴿عِنْد رَبِّي فِي كِتاب﴾ هُوَ اللَّوْح المَحْفُوظ يُجازِيهِمْ عَلَيْها يَوْم القِيامَة ﴿لا يَضِلّ﴾ يَغِيب ﴿رَبِّي﴾ عَنْ شَيْء ﴿ولا يَنْسى﴾ رَبِّي شَيْئًا"],[53,53,"﴿الَّذِي جَعَلَ لَكُمْ﴾ فِي جُمْلَة الخَلْق ﴿الأَرْض مَهْدًا﴾ فِراشًا ﴿وسَلَكَ﴾ سَهَّلَ ﴿لَكُمْ فِيها سُبُلًا﴾ طُرُقًا ﴿وأَنْزَلَ مِن السَّماء ماء﴾ مَطَرًا قالَ تَعالى تَتْمِيمًا لِما وصَفَهُ بِهِ مُوسى وخِطابًا لِأَهْلِ مَكَّة ﴿فَأَخْرَجْنا بِهِ أزْواجًا﴾ أصْنافًا ﴿مِن نَبات شَتّى﴾ صِفَة أزْواجًا أيْ مُخْتَلِفَة الأَلْوان والطُّعُوم وغَيْرهما وشَتّى جَمْع شَتِيت كَمَرِيضٍ ومَرْضى مِن شَتَّ الأَمْر تَفَرَّقَ"],[54,54,"﴿كُلُوا﴾ مِنها ﴿وارْعَوْا أنْعامكُمْ﴾ فِيها جَمْع نَعَم وهِيَ الإبِل والبَقَر والغَنَم يُقال رَعَتْ الأَنْعام ورَعَيْتها والأَمْر لِلْإباحَةِ وتَذْكِير النِّعْمَة والجُمْلَة حال مِن ضَمِير أخْرَجْنا أيْ مُبِيحِينَ لَكُمْ الأَكْل ورَعْي الأَنْعام ﴿إنّ فِي ذَلِكَ﴾ المَذْكُور هُنا ﴿لَآيات﴾ لَعِبَرًا ﴿لِأُولِي النُّهى﴾ لِأَصْحابِ العُقُول جَمْع نُهْيَة كَغُرْفَةٍ وغُرَف سُمِّيَ بِهِ العَقْل لِأَنَّهُ يَنْهى صاحِبه عَنْ ارْتِكاب القَبائِح"],[55,55,"﴿مِنها﴾ أيْ مِن الأَرْض ﴿خَلَقْناكُمْ﴾ بِخَلْقِ أبِيكُمْ آدَم مِنها ﴿وفِيها نُعِيدكُمْ﴾ مَقْبُورِينَ بَعْد المَوْت ﴿ومِنها نُخْرِجكُمْ﴾ عِنْد البَعْث ﴿تارَة﴾ مَرَّة ﴿أُخْرى﴾ كَما أخْرَجْناكُمْ عِنْد ابْتِداء خَلْقكُمْ"],[56,56,"﴿ولَقَدْ أرَيْناهُ﴾ أيْ أبْصَرْنا فِرْعَوْن ﴿آياتنا كُلّها﴾ التِّسْع ﴿فَكَذَّبَ﴾ بِها وزَعَمَ أنَّها سِحْر ﴿وأَبى﴾ أنْ يُوَحِّد اللَّه تَعالى"],[57,57,"﴿قالَ أجِئْتنا لِتُخْرِجنا مِن أرْضنا﴾ مِصْر ويَكُون لَك المُلْك فِيها"],[58,58,"﴿فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِثْلِهِ﴾ يُعارِضُهُ ﴿فاجْعَلْ بَيْننا وبَيْنك مَوْعِدًا﴾ لِذَلِكَ ﴿لا نُخْلِفهُ نَحْنُ ولا أنْتَ مَكانًا﴾ مَنصُوب بِنَزْعِ الخافِض فِي ﴿سُوًى﴾ بِكَسْرِ أوَّله وضَمّه أيْ وسَطًا تَسْتَوِي إلَيْهِ مَسافَة الجائِي مِن الطَّرَفَيْنِ"],[59,59,"﴿قالَ﴾ مُوسى ﴿مَوْعِدكُمْ يَوْم الزِّينَة﴾ يَوْم عِيد لَهُمْ يَتَزَيَّنُونَ فِيهِ ويَجْتَمِعُونَ ﴿وأَنْ يُحْشَر النّاس﴾ يُجْمَع أهْل مِصْر ﴿ضُحًى﴾ وقَّتَهُ لِلنَّظَرِ فِيما يَقَع"],[60,60,"﴿فَتَوَلّى فِرْعَوْن﴾ أدْبَرَ ﴿فَجَمَعَ كَيْده﴾ أيْ ذَوِي كَيْده مِن السَّحَرَة ﴿ثُمَّ أتى﴾ بِهِمْ المَوْعِد"],[61,61,"﴿قالَ لَهُمْ مُوسى﴾ وهُمْ اثْنانِ وسَبْعُونَ مَعَ كُلّ واحِد حَبْل وعَصًا ﴿ويْلكُمْ﴾ أيْ ألْزَمَكُمْ اللَّه الوَيْل ﴿لا تَفْتَرُوا عَلى اللَّه كَذِبًا﴾ بِإشْراكِ أحَد مَعَهُ ﴿فَيُسْحِتَكُمْ﴾ بِضَمِّ الياء وكَسْر الحاء وبِفَتْحِهِما أيْ يُهْلِككُمْ ﴿بِعَذابٍ﴾ مِن عِنْده ﴿وقَدْ خابَ﴾ خَسِرَ ﴿مَن افْتَرى﴾ كَذَبَ عَلى اللَّه"],[62,62,"﴿فَتَنازَعُوا أمْرهمْ بَيْنهمْ﴾ فِي مُوسى وأَخِيهِ ﴿وأَسَرُّوا النَّجْوى﴾ أيْ الكَلام بَيْنهمْ فِيهِما"],[63,63,"﴿قالُوا﴾ لِأَنْفُسِهِمْ ﴿إنْ هَذانِ﴾ وهُوَ مُوافِق لِلُغَةِ مَن يَأْتِي فِي المُثَنّى بِالأَلِفِ فِي أحْواله الثَّلاث ولِأَبِي عَمْرو: هَذَيْنِ ﴿لَساحِرانِ يُرِيدانِ أنْ يُخْرِجاكُمْ مِن أرْضِكُمْ بِسِحْرِهِما ويَذْهَبا بِطَرِيقَتِكُمْ المُثْلى﴾ مُؤَنَّث أمْثَل بِمَعْنى أشْرَف أيْ بِأَشْرافِكُمْ بِمَيْلِهِمْ إلَيْهِما لِغَلَبَتِهِما"],[64,64,"﴿فاجْمَعُوا كَيْدَكُمْ﴾ مِن السِّحْر بِهَمْزَةِ وصْل وفَتْح المِيم مِن جَمَعَ أيْ لَمَّ وبِهَمْزَةِ قَطْع وكَسْر المِيم مِن أجْمَعَ أحْكَمَ ﴿ثُمَّ ائْتُوا صَفًّا﴾ حال أيْ مُصْطَفِّينَ ﴿وقَدْ أفْلَحَ﴾ فازَ ﴿اليَوْم مَن اسْتَعْلى﴾ غَلَبَ"],[65,65,"﴿قالُوا يا مُوسى﴾ اخْتَرْ ﴿إمّا أنْ تُلْقِيَ﴾ عَصاك أوَّلًا ﴿وإمّا أنْ نَكُون أوَّل مَن ألْقى﴾ عَصاهُ"],[66,66,"﴿قالَ بَلْ ألْقُوا﴾ فَأَلْقَوْا ﴿فَإذا حِبالهمْ وعِصِيّهمْ﴾ أصْله عُصُوو قُلِبَتْ الواوانِ ياءَيْنِ وكُسِرَتْ العَيْن والصّاد ﴿يُخَيَّل إلَيْهِ مِن سِحْرهمْ أنَّها﴾ حَيّات ﴿تَسْعى﴾ عَلى بُطُونها"],[67,67,"﴿فَأَوْجَسَ﴾ أحَسَّ ﴿فِي نَفْسه خِيفَة مُوسى﴾ أيْ خافَ مِن جِهَة أنَّ سِحْرهمْ مِن جِنْس مُعْجِزَته أنْ يَلْتَبِس أمْره عَلى النّاس فَلا يُؤْمِنُوا بِهِ"],[68,68,"﴿قُلْنا﴾ لَهُ ﴿لا تَخَفْ إنّك أنْتَ الأَعْلى﴾ عَلَيْهِمْ بِالغَلَبَةِ"],[69,69,"﴿وأَلْقِ ما فِي يَمِينك﴾ وهِيَ عَصاهُ ﴿تَلْقَف﴾ تَبْتَلِع ﴿ما صَنَعُوا إنّما صَنَعُوا كَيْد ساحِرٍ﴾ أيْ جِنْسه ﴿ولا يُفْلِح السّاحِر حَيْثُ أتى﴾ بِسِحْرِهِ فَأَلْقى مُوسى عَصاهُ فَتَلَقَّفَتْ كُلّ ما صَنَعُوهُ"],[70,70,"﴿فَأُلْقِيَ السَّحَرَة سُجَّدًا﴾ خَرُّوا ساجِدِينَ لِلَّهِ تَعالى"],[71,71,"﴿قالَ﴾ فِرْعَوْن ﴿آمَنتُمْ﴾ بِتَحْقِيقِ الهَمْزَتَيْنِ وإبْدال الثّانِيَة ألِفًا ﴿لَهُ قَبْل أنْ آذَن﴾ أنا ﴿لَكُمْ إنّهُ لَكَبِيركُمْ﴾ مُعَلِّمكُمْ ﴿الَّذِي عَلَّمَكُمْ السِّحْر فَلَأُقَطِّعَنَّ أيْدِيَكُمْ وأَرْجُلكُمْ مِن خِلاف﴾ حال بِمَعْنى مُخْتَلِفَة أيْ الأَيْدِي اليُمْنى والأَرْجُل اليُسْرى ﴿ولَأُصَلِّبَنكُمْ فِي جُذُوع النَّخْل﴾ أيْ عَلَيْها ﴿ولَتَعْلَمُنَّ أيّنا﴾ يَعْنِي نَفْسه ورَبّ مُوسى ﴿أشَدّ عَذابًا وأَبْقى﴾ أدْوَم عَلى مُخالَفَته"],[72,72,"﴿قالُوا لَنْ نُؤْثِرك﴾ نَخْتارك ﴿عَلى ما جاءَنا مِن البَيِّنات﴾ الدّالَّة عَلى صِدْق مُوسى ﴿والَّذِي فَطَرَنا﴾ خَلَقَنا قَسَم أوْ عَطْف عَلى ما ﴿فاقْضِ ما أنْتَ قاضٍ﴾ أيْ اصْنَعْ ما قُلْته ﴿إنّما تَقْضِي هَذِهِ الحَياة الدُّنْيا﴾ النَّصْب عَلى الِاتِّساع أيْ فِيها وتُجْزى عَلَيْهِ فِي الآخِرَة"],[73,73,"﴿إنّا آمَنّا بِرَبِّنا لِيَغْفِر لَنا خَطايانا﴾ مِن الإشْراك وغَيْره ﴿وما أكْرَهْتنا عَلَيْهِ مِن السِّحْر﴾ تَعَلُّمًا وعَمَلًا لِمُعارَضَةِ مُوسى ﴿واللَّه خَيْر﴾ مِنك ثَوابًا إذا أُطِيعَ ﴿وأَبْقى﴾ مِنك عَذابًا إذا عُصِيَ"],[74,74,"﴿إنّهُ مَن يَأْتِ رَبّه مُجْرِمًا﴾ كافِرًا كَفِرْعَوْن ﴿فَإنَّ لَهُ جَهَنَّم لا يَمُوت فِيها﴾ فَيَسْتَرِيح ﴿ولا يَحْيا﴾ حَياة تَنْفَعهُ"],[75,75,"﴿ومَن يَأْتِهِ مُؤْمِنًا قَدْ عَمِلَ الصّالِحات﴾ الفَرائِض والنَّوافِل ﴿فَأُولَئِكَ لَهُمْ الدَّرَجات العُلى﴾ جَمْع عُلْيا مُؤَنَّث أعْلى"],[76,76,"﴿جَنّات عَدْن﴾ أيْ إقامَة ﴿تَجْرِي مِن تَحْتها الأَنْهار خالِدِينَ فِيها وذَلِكَ جَزاء مَن تَزَكّى﴾ تَطَهَّرَ مِن الذُّنُوب"],[77,77,"﴿ولَقَدْ أوْحَيْنا إلى مُوسى أنْ أسْرِ بِعِبادِي﴾ بِهَمْزَةِ قَطْع مِن أسْرى وبِهَمْزَةِ وصْل وكَسْر النُّون مِن سَرى لُغَتانِ أيْ سِرْ بِهِمْ لَيْلًا مِن أرْض مِصْر ﴿فاضْرِبْ لَهُمْ﴾ اجْعَلْ لَهُمْ بِالضَّرْبِ بِعَصاك ﴿طَرِيقًا فِي البَحْر يَبَسًا﴾ أيْ يابِسًا فامْتَثَلَ ما أُمِرَ بِهِ وأَيْبَسَ اللَّه الأَرْض فَمَرُّوا فيها ﴿لا تَخاف دَرَكًا﴾ أيْ أنْ يُدْرِكك فِرْعَوْن ﴿ولا تَخْشى﴾ غَرَقًا"],[78,78,"﴿فَأَتْبَعَهُمْ فِرْعَوْن بِجُنُودِهِ﴾ وهُوَ مَعَهُمْ ﴿فَغَشِيَهُمْ مِن اليَمّ﴾ أيْ البَحْر ﴿ما غَشِيَهُمْ﴾ فَأَغْرَقَهُمْ"],[79,79,"﴿وأَضَلَّ فِرْعَوْن قَوْمه﴾ بِدُعائِهِمْ إلى عِبادَته ﴿وما هَدى﴾ بَلْ أوْقَعَهُمْ فِي الهَلاك خِلاف قَوْله ﴿وما أهْدِيكُمْ إلّا سَبِيل الرَّشاد﴾"],[80,80,"﴿يا بَنِي إسْرائِيل قَدْ أنْجَيْناكُمْ مِن عَدُوّكُمْ﴾ فِرْعَوْن بِإغْراقِهِ ﴿وواعَدْناكُمْ جانِب الطُّور الأَيْمَن﴾ فَنُؤْتِي مُوسى التَّوْراة لِلْعَمَلِ بِها ﴿ونَزَّلْنا عَلَيْكُمْ المَنّ والسَّلْوى﴾ هُما الترنجبين والطَّيْر السُّمانى بِتَخْفِيفِ المِيم والقَصْر والمُنادى مَن وُجِدَ مِن اليَهُود زَمَن النَّبِيّ ﷺ وخُوطِبُوا بِما أنْعَمَ اللَّه بِهِ عَلى أجْدادهمْ زَمَن النَّبِيّ مُوسى تَوْطِئَة لِقَوْلِهِ تَعالى لَهُمْ:"],[81,81,"﴿كُلُوا مِن طَيِّبات ما رَزَقْناكُمْ﴾ أيْ المُنْعَم بِهِ عَلَيْكُمْ ﴿ولا تَطْغَوْا فِيهِ﴾ بِأَنْ تَكْفُرُوا النِّعْمَة بِهِ ﴿فَيَحِلّ عَلَيْكُمْ غَضَبِي﴾ بِكَسْرِ الحاء: أيْ يَجِب وبِضَمِّها أيْ يَنْزِل ﴿ومَن يَحْلِلْ عَلَيْهِ غَضَبِي﴾ بِكَسْرِ اللّام وضَمّها ﴿فَقَدْ هَوى﴾ سَقَطَ فِي النّار"],[82,82,"﴿وإنِّي لَغَفّار لِمَن تابَ﴾ مِن الشِّرْك ﴿وآمَنَ﴾ وحَّدَ اللَّه ﴿وعَمِلَ صالِحًا﴾ يَصْدُق بِالفَرْضِ والنَّفْل ﴿ثُمَّ اهْتَدى﴾ بِاسْتِمْرارِهِ عَلى ما ذُكِرَ إلى مَوْته"],[83,83,"﴿وما أعْجَلَك عَنْ قَوْمك﴾ لِمَجِيءِ مِيعاد أخْذ التَّوْراة"],[84,84,"﴿قالَ هُمْ أُولاءِ﴾ أيْ بِالقُرْبِ مِنِّي يَأْتُونَ ﴿عَلى أثَرِي وعَجِلْت إلَيْك رَبّ لِتَرْضى﴾ عَنِّي: أيْ زِيادَة فِي رِضاك وقَبْل الجَواب أتى بِالِاعْتِذارِ حَسَب ظَنّه وتَخَلُّف المَظْنُون لَمّا"],[85,85,"﴿قالَ﴾ تَعالى ﴿فَإنّا قَدْ فَتَنّا قَوْمك مِن بَعْدك﴾ أيْ بَعْد فِراقك لَهُمْ ﴿وأَضَلَّهُمْ السّامِرِيّ﴾ فَعَبَدُوا العِجْل"],[86,86,"﴿فَرَجَعَ مُوسى إلى قَوْمه غَضْبان﴾ مِن جِهَتهمْ ﴿أسِفًا﴾ شَدِيد الحُزْن ﴿قالَ يا قَوْم ألَمْ يَعِدكُمْ رَبّكُمْ وعْدًا حَسَنًا﴾ أيْ صِدْقًا أنَّهُ يُعْطِيكُمْ التَّوْراة ﴿أفَطالَ عَلَيْكُمْ العَهْد﴾ مُدَّة مُفارَقَتِي إيّاكُمْ ﴿أمْ أرَدْتُمْ أنْ يَحِلّ﴾ بِعِبادَتِكُمْ العِجْل ﴿فَأَخْلَفْتُمْ مَوْعِدِي﴾ وتَرَكْتُمْ المَجِيء بَعْدِي"],[87,87,"﴿قالُوا ما أخْلَفْنا مَوْعِدك بِمَلْكِنا﴾ مُثَلَّث المِيم أيْ بِقُدْرَتِنا أوْ أمْرنا ﴿ولَكِنّا حُمِّلْنا﴾ بِفَتْحِ الحاء مُخَفَّفًا وبِضَمِّها وكَسْر المِيم مُشَدَّدًا ﴿أوْزارًا﴾ أثْقالًا ﴿مِن زِينَة القَوْم﴾ أيْ حُلِيّ قَوْم فِرْعَوْن اسْتَعارَها مِنهُمْ بَنُو إسْرائِيل بِعِلَّةِ عُرْس فَبَقِيَتْ عِنْدهمْ ﴿فَقَذَفْناها﴾ طَرَحْناها فِي النّار بِإمْرِ السّامِرِيّ ﴿فَكَذَلِكَ﴾ كَما ألْقَيْنا ﴿ألْقى السّامِرِيّ﴾ ما مَعَهُ مِن حُلِيّهمْ ومِن التُّراب الَّذِي أخَذَهُ مِن أثَر حافِر فَرَس جِبْرِيل عَلى الوَجْه الآتِي"],[88,88,"﴿فَأَخْرَجَ لَهُمْ عِجْلًا﴾ صاغَهُ مِن الحُلِيّ ﴿جَسَدًا﴾ لَحْمًا ودَمًا ﴿لَهُ خُوار﴾ أيْ صَوْت يُسْمَع أيْ انْقَلَبَ كَذَلِكَ بِسَبَبِ التُّراب الَّذِي أثَرُهُ الحَياةُ فِيما يُوضَع فِيهِ ووَضَعَهُ بَعْد صَوْغه فِي فَمه ﴿فَقالُوا﴾ أيْ السّامِرِيّ وأَتْباعه ﴿هَذا إلَهكُمْ وإلَه مُوسى فَنَسِيَ﴾ مُوسى رَبّه هُنا وذَهَبَ يَطْلُبهُ"],[89,89,"﴿أفَلا يَرَوْنَ أ﴾ أنْ مُخَفَّفَة مِن الثَّقِيلَة واسْمها مَحْذُوف أيْ أنَّهُ ﴿لا يَرْجِع﴾ العِجْل ﴿إلَيْهِمْ قَوْلًا﴾ أيْ لا يَرُدّ لَهُمْ جَوابًا ﴿ولا يَمْلِك لَهُمْ ضَرًّا﴾ أيْ دَفْعه ﴿ولا نَفْعًا﴾ أيْ جَلْبه أيْ فَكَيْفَ يَتَّخِذ إلَهًا ؟"],[90,90,"﴿ولَقَدْ قالَ لَهُمْ هارُون مِن قَبْل﴾ أيْ قَبْل أنْ يَرْجِع مُوسى ﴿يا قَوْم إنّما فَتَنْتُمْ بِهِ وإنَّ رَبّكُمْ الرَّحْمَن فاتَّبِعُونِي﴾ فِي عِبادَته ﴿وأَطِيعُوا أمْرِي﴾ فِيها"],[91,91,"﴿قالُوا لَنْ نَبْرَحَ﴾ نَزال ﴿عَلَيْهِ عاكِفِينَ﴾ عَلى عِبادَته مُقِيمِينَ"],[92,92,"﴿قالَ﴾ مُوسى بَعْد رُجُوعه ﴿يا هارُون ما مَنَعَك إذْ رَأَيْتهمْ ضَلُّوا﴾ بِعِبادَتِهِ"],[93,93,"﴿أ﴾ نْ ﴿لّا﴾ لا زائِدَة ﴿أفَعَصَيْت أمْرِي﴾ بِإقامَتِك بَيْن مَن يَعْبُد غَيْر اللَّه تَعالى"],[94,94,"﴿قالَ﴾ هارُون ﴿يَبْنَؤُمَّ﴾ بِكَسْرِ المِيم وفَتْحها أرادَ أُمِّي وذِكْرها أعْطَف لِقَلْبِهِ ﴿لا تَأْخُذ بِلِحْيَتِي﴾ وكانَ أخَذَها بِشِمالِهِ ﴿ولا بِرَأْسِي﴾ وكانَ أخَذَ شَعَره بِيَمِينِهِ غَضَبًا ﴿إنِّي خَشِيت﴾ لَوْ اتَّبَعْتُك ولا بُدّ أنْ يَتَّبِعَنِي جَمْع مِمَّنْ لَمْ يَعْبُدُوا العِجْل ﴿أنْ تَقُول فَرَّقْت بَيْن بَنِي إسْرائِيل﴾ وتَغْضَب عَلَيَّ ﴿ولَمْ تَرْقُب﴾ تَنْتَظِر ﴿قَوْلِي﴾ فِيما رَأَيْته فِي ذَلِكَ"],[95,95,"﴿قالَ فَما خَطْبك﴾ شَأْنك الدّاعِي إلى ما صَنَعْت"],[96,96,"﴿قالَ بَصُرْت بِما لَمْ يَبْصُرُوا بِهِ﴾ بِالياءِ والتّاء أيْ عَلِمْت ما لَمْ يَعْلَمُوهُ ﴿فَقَبَضْت قَبْضَة مِن﴾ تُراب ﴿أثَر﴾ حافِر فَرَس ﴿الرَّسُول﴾ جِبْرِيل ﴿فَنَبَذْتها﴾ ألْقَيْتها فِي صُورَة العِجْل المُصاغ ﴿وكَذَلِكَ سَوَّلَتْ﴾ زَيَّنَتْ ﴿لِي نَفْسِي﴾ وأُلْقِيَ فِيها أنَّ آخِذ قَبْضَة مِن تُراب ما ذُكِرَ وأُلْقِيها عَلى ما لا رُوح لَهُ يَصِير لَهُ رُوح ورَأَيْت قَوْمك طَلَبُوا مِنك أنْ تَجْعَل لَهُمْ إلَهًا فَحَدَّثَتْنِي نَفْسِي أنْ يَكُون ذَلِكَ العِجْل إلَههمْ"],[97,97,"﴿قالَ﴾ لَهُ مُوسى ﴿فاذْهَبْ﴾ مِن بَيْننا ﴿فَإنَّ لَك فِي الحَياة﴾ أيْ مُدَّة حَياتك ﴿أنْ تَقُول﴾ لِمَن رَأَيْته ﴿لا مِساس﴾ أيْ لا تَقْرَبنِي فَكانَ يَهِيم فِي البَرِيَّة وإذا مَسَّ أحَدًا أوْ مَسَّهُ أحَد حُمّا جَمِيعًا ﴿وإنَّ لَك مَوْعِدًا﴾ لِعَذابِك ﴿لَنْ تُخْلِفهُ﴾ بِكَسْرِ اللّام: أيْ لَنْ تَغِيب عَنْهُ وبِفَتْحِها أيْ بَلْ تُبْعَث إلَيْهِ ﴿وانْظُرْ إلى إلَهك الَّذِي ظَلْتَ﴾ أصْله ظَلِلْت بِلامَيْنِ أُولاهُما مَكْسُورَة حُذِفَتْ تَخْفِيفًا أيْ دُمْت ﴿عَلَيْهِ عاكِفًا﴾ أيْ مُقِيمًا تَعْبُدهُ ﴿لَنُحَرِّقَنَّهُ﴾ بِالنّارِ ﴿ثُمَّ لَنَنْسِفَنَّهُ فِي اليَمّ نَسْفًا﴾ نُذْرِيَنَّهُ فِي هَواء البَحْر وفَعَلَ مُوسى بَعْد ذَبْحه ما ذَكَرَهُ"],[98,98,"﴿إنّما إلَهكُمْ اللَّه الَّذِي لا إلَه إلّا هُوَ وسِعَ كُلّ شَيْء عِلْمًا﴾ تَمْيِيز مُحَوَّل عَنْ الفاعِل أيْ وسِعَ عِلْمه كُلّ شَيْء"],[99,99,"﴿كَذَلِكَ﴾ أيْ كَما قَصَصْنا عَلَيْك يا مُحَمَّد هَذِهِ القِصَّة ﴿نَقُصّ عَلَيْك مِن أنْباء﴾ أخْبار ﴿ما قَدْ سَبَقَ﴾ مِن الأُمَم ﴿وقَدْ آتَيْناك﴾ أعْطَيْناك ﴿مِن لَدُنّا﴾ مِن عِنْدنا ﴿ذِكْرًا﴾ قُرْآنًا"],[100,100,"﴿مَن أعْرَضَ عَنْهُ﴾ فَلَمْ يُؤْمِن بِهِ ﴿فَإنَّهُ يَحْمِل يَوْم القِيامَة وِزْرًا﴾ حِمْلًا ثَقِيلًا مِن الإثْم"],[101,101,"﴿خالِدِينَ فِيهِ﴾ أيْ فِي عَذاب الوِزْر ﴿وساءَ لَهُمْ يَوْم القِيامَة حِمْلًا﴾ تَمْيِيز مُفَسِّر لِلضَّمِيرِ فِي ساءَ والمَخْصُوص بِالذَّمِّ مَحْذُوف تَقْدِيره وِزْرهمْ واللّام لِلْبَيانِ ويُبْدَل مِن يَوْم القِيامَة"],[102,102,"﴿يَوْم يُنْفَخ فِي الصُّور﴾ القَرْن النَّفْخَة الثّانِيَة ﴿ونَحْشُر المُجْرِمِينَ﴾ الكافِرِينَ ﴿يَوْمئِذٍ زُرْقًا﴾ عُيُونهمْ مَعَ سَواد وُجُوههمْ"],[103,103,"﴿يَتَخافَتُونَ بَيْنهمْ﴾ يَتَسارُّونَ ﴿إنْ﴾ ما ﴿لَبِثْتُمْ﴾ فِي الدُّنْيا ﴿إلّا عَشْرًا﴾ مِن اللَّيالِي بِأَيّامِها"],[104,104,"﴿نَحْنُ أعْلَم بِما يَقُولُونَ﴾ فِي ذَلِكَ: أيْ لَيْسَ كَما قالُوا ﴿إذْ يَقُول أمْثَلهمْ﴾ أعْدَلهمْ ﴿طَرِيقَة﴾ فِيهِ ﴿إنْ لَبِثْتُمْ إلّا يَوْمًا﴾ يَسْتَقِلُّونَ لُبْثهمْ فِي الدُّنْيا جِدًّا لِما يُعايِنُونَهُ فِي الآخِرَة مِن أهْوالها"],[105,105,"﴿ويَسْأَلُونَك عَنْ الجِبال﴾ كَيْفَ تَكُون يَوْم القِيامَة ﴿فَقُلْ﴾ لَهُمْ ﴿يَنْسِفها رَبِّي نَسْفًا﴾ بِأَنْ يُفَتِّتها كالرَّمْلِ السّائِل ثُمَّ يُطِيرها بِالرِّياحِ"],[106,106,"﴿فَيَذَرها قاعًا﴾ مُنْبَسِطًا ﴿صَفْصَفًا﴾ مُسْتَوِيًا"],[107,107,"﴿لا تَرى فِيها عِوَجًا﴾ انْخِفاضًا ﴿ولا أمْتًا﴾ ارْتِفاعًا"],[108,108,"﴿يَوْمئِذٍ﴾ أيْ يَوْم إذْ نُسِفَتْ الجِبال ﴿يَتَّبِعُونَ﴾ أيْ النّاس بَعْد القِيام مِن القُبُور ﴿الدّاعِي﴾ إلى المَحْشَر بِصَوْتِهِ وهُوَ إسْرافِيل يَقُول: هَلُمُّوا إلى عَرْض الرَّحْمَن ﴿لا عِوَج لَهُ﴾ أيْ لِاتِّباعِهِمْ: أيْ لا يَقْدِرُونَ أنْ لا يَتَّبِعُوا ﴿وخَشَعَتْ﴾ سَكَنَتْ ﴿الأَصْوات لِلرَّحْمَنِ فَلا تَسْمَع إلّا هَمْسًا﴾ صَوْت وطْء الأَقْدام فِي نَقْلها إلى المَحْشَر كَصَوْتِ أخْفاف الإبِل فِي مَشْيها"],[109,109,"﴿يَوْمئِذٍ لا تَنْفَع الشَّفاعَة﴾ لا تَنْفَع الشَّفاعَة أحَدًا ﴿إلّا مَن أذِنَ لَهُ الرَّحْمَن﴾ أنْ يَشْفَع لَهُ ﴿ورَضِيَ لَهُ قَوْلًا﴾ بِأَنْ يَقُول: لا إلَه إلّا اللَّه"],[110,110,"﴿يَعْلَم ما بَيْن أيْدِيهمْ﴾ مِن أُمُور الآخِرَة ﴿وما خَلْفهمْ﴾ مِن أُمُور الدُّنْيا ﴿ولا يُحِيطُونَ بِهِ عِلْمًا﴾ لا يَعْلَمُونَ ذَلِكَ"],[111,111,"﴿وعَنَتْ الوُجُوه﴾ خَضَعَتْ ﴿لِلْحَيِّ القَيُّوم﴾ أيْ اللَّه ﴿وقَدْ خابَ﴾ خَسِرَ ﴿مَن حَمَلَ ظُلْمًا﴾ أيْ شِرْكًا"],[112,112,"﴿ومَن يَعْمَل مِن الصّالِحات﴾ الطّاعات ﴿وهُوَ مُؤْمِن فَلا يَخاف ظُلْمًا﴾ بِزِيادَةٍ فِي سَيِّئاته ﴿ولا هَضْمًا﴾ بِنَقْصٍ مِن حَسَناته"],[113,113,"﴿وكَذَلِكَ﴾ مَعْطُوف عَلى كَذَلِكَ نَقُصّ: أيْ مِثْل إنْزال ما ذُكِرَ ﴿أنْزَلْناهُ﴾ أيْ القُرْآن ﴿قُرْآنًا عَرَبِيًّا وصَرَّفْنا﴾ كَرَّرْنا ﴿فِيهِ مِن الوَعِيد لَعَلَّهُمْ يَتَّقُونَ﴾ يَتَّقُونَ الشِّرْك ﴿أوْ يُحْدِث﴾ يُحْدِث القُرْآن ﴿لَهُمْ ذِكْرًا﴾ بِهَلاكِ مَن تَقَدَّمَهُمْ مِن الأُمَم فَيَعْتَبِرُونَ"],[114,114,"﴿فَتَعالى اللَّه المَلِك الحَقّ﴾ عَمّا يَقُول المُشْرِكُونَ ﴿ولا تَعْجَل بِالقُرْآنِ﴾ أيْ بِقِراءَتِهِ ﴿مِن قَبْل أنْ يُقْضى إلَيْك وحْيه﴾ أيْ يَفْرُغ جِبْرِيل مِن إبْلاغه ﴿وقُلْ رَبّ زِدْنِي عِلْمًا﴾ أيْ بِالقُرْآنِ فَكُلَّما أُنْزِلَ عَلَيْهِ شَيْء مِنهُ زادَ بِهِ عِلْمه"],[115,115,"﴿ولَقَدْ عَهِدْنا إلى آدَم﴾ وصَّيْناهُ أنْ لا يَأْكُل مِن الشَّجَرَة ﴿مِن قَبْل﴾ أيْ قَبْل أكْله مِنها ﴿فَنَسِيَ﴾ تَرَكَ عَهْدنا ﴿ولَمْ نَجِد لَهُ عَزْمًا﴾ حَزْمًا وصَبْرًا عَمّا نَهَيْناهُ عَنْهُ"],[116,116,"﴿و﴾ اذْكُر ﴿إذْ قُلْنا لِلْمَلائِكَةِ اُسْجُدُوا لِآدَم فَسَجَدُوا إلّا إبْلِيس﴾ وهُوَ أبُو الجِنّ كانَ يَصْحَب المَلائِكَة ويَعْبُد اللَّه مَعَهُمْ ﴿أبى﴾ عَنْ السُّجُود لِآدَم ﴿قالَ أنا خَيْر مِنهُ﴾"],[117,117,"﴿فَقُلْنا يا آدَم إنّ هَذا عَدُوّ لَك ولِزَوْجِك﴾ حَوّاء بِالمَدِّ ﴿فَلا يُخْرِجَنكُما مِن الجَنَّة فَتَشْقى﴾ تَتْعَب بِالحَرْثِ والزَّرْع والحَصْد والطَّحْن والخَبْز وغَيْر ذَلِكَ واقْتَصَرَ عَلى شَقائِهِ لِأَنَّ الرَّجُل يَسْعى عَلى زَوْجَته"],[118,118,"﴿إنّ لَك أ﴾ نْ ﴿لا﴾"],[119,119,"﴿وأَنَّك﴾ بِفَتْحِ الهَمْزَة وكَسْرها عَطْف عَلى اسْم إنّ وجُمْلَتها ﴿لا تَظْمَأ فِيها﴾ تَعْطَش ﴿ولا تَضْحى﴾ لا يَحْصُل لَك حَرّ شَمْس الضُّحى لِانْتِفاءِ الشَّمْس فِي الجَنَّة"],[120,120,"﴿فَوَسْوَسَ إلَيْهِ الشَّيْطان قالَ يا آدَم هَلْ أدُلّك عَلى شَجَرَة الخُلْد﴾ أيْ الَّتِي يُخَلَّد مَن يَأْكُل مِنها ﴿ومُلْك لا يَبْلى﴾ لا يَفْنى وهُوَ لازِم الخُلْد"],[121,121,"﴿فَأَكَلا﴾ أيْ آدَم وحَوّاء ﴿مِنها فَبَدَتْ لَهُما سَوْآتهما﴾ أيْ ظَهَرَ لِكُلٍّ مِنهُما قُبُله وقُبُل الآخَر ودُبُره وسُمِّيَ كُلّ مِنهُما سَوْأَة لِأَنَّ انْكِشافه يَسُوء صاحِبه ﴿وطَفِقا يَخْصِفانِ﴾ أخَذا يُلْزِقانِ ﴿عَلَيْهِما مِن ورَق الجَنَّة﴾ لِيَسْتَتِرا بِهِ ﴿وعَصى آدَم رَبّه فَغَوى﴾ بِالأَكْلِ مِن الشَّجَرَة"],[122,122,"﴿ثُمَّ اجْتَباهُ رَبّه﴾ قَرَّبَهُ ﴿فَتابَ عَلَيْهِ﴾ قَبْل تَوْبَته ﴿وهَدى﴾ أيْ هَداهُ إلى المُداوَمَة عَلى التَّوْبَة"],[123,123,"﴿قالَ اهْبِطا﴾ أيْ آدَم وحَوّاء بِما اشْتَمَلْتُما عَلَيْهِ مِن ذُرِّيَّتكُما ﴿مِنها﴾ مِن الجَنَّة ﴿جَمِيعًا بَعْضكُمْ﴾ بَعْض الذُّرِّيَّة ﴿لِبَعْضٍ عَدُوّ﴾ مِن ظُلْم بَعْضهمْ بَعْضًا ﴿فَإمّا﴾ فِيهِ إدْغام نُون إنْ الشَّرْطِيَّة فِي ما المَزِيدَة ﴿يَأْتِيَنكُمْ مِنِّي هُدًى فَمَن اتَّبَعَ هُدايَ﴾ القُرْآن ﴿فَلا يَضِلّ﴾ فِي الدُّنْيا ﴿ولا يَشْقى﴾ فِي الآخِرَة"],[124,124,"﴿ومَن أعْرَضَ عَنْ ذِكْرِي﴾ القُرْآن فَلَمْ يُؤْمِن بِهِ ﴿فَإنَّ لَهُ مَعِيشَة ضَنْكًا﴾ بِالتَّنْوِينِ مَصْدَر بِمَعْنى ضَيِّقَة وفُسِّرَتْ فِي حَدِيث بِعَذابِ الكافِر فِي قَبْره ﴿ونَحْشُرهُ﴾ أيْ المُعْرِض عَنْ القُرْآن ﴿يَوْم القِيامَة أعْمى﴾ أعْمى البَصَر"],[125,125,"﴿قالَ رَبّ لَمْ حَشَرْتنِي أعْمى وقَدْ كُنْت بَصِيرًا﴾ فِي الدُّنْيا وعِنْد البَعْث"],[126,126,"﴿قالَ﴾ الأَمْر ﴿كَذَلِكَ أتَتْك آيَتنا فَنَسِيتها﴾ تَرَكْتها ولَمْ تُؤْمِن بِها ﴿وكَذَلِكَ﴾ مِثْل نِسْيانك آياتنا ﴿اليَوْم تُنْسى﴾ تُتْرَك فِي النّار"],[127,127,"﴿وكَذَلِكَ﴾ ومِثْل جَزائِنا مَن أعْرَضَ عَنْ القُرْآن ﴿نَجْزِي مَن أسْرَفَ﴾ أشْرَكَ ﴿ولَمْ يُؤْمِن بِآياتِ رَبّه ولَعَذاب الآخِرَة أشَدّ﴾ مِن عَذاب الدُّنْيا وعَذاب القَبْر ﴿وأَبْقى﴾ أدْوَم"],[128,128,"﴿أفَلَمْ يَهْدِ﴾ يَتَبَيَّن ﴿لَهُمْ﴾ لِكُفّارِ مَكَّة ﴿كَمْ﴾ خَبَرِيَّة مَفْعُول ﴿أهْلَكْنا﴾ أيْ كَثِيرًا إهْلاكنا ﴿قَبْلهمْ مِن القُرُون﴾ أيْ الأُمَم الماضِيَة بِتَكْذِيبِ الرُّسُل ﴿يَمْشُونَ﴾ حال مِن ضَمِير لَهُمْ ﴿فِي مَساكِنهمْ﴾ فِي سَفَرهمْ إلى الشّام وغَيْرها فَيَعْتَبِرُوا وما ذُكِرَ مِن أخْذ إهْلاك مِن فِعْله الخالِي عَنْ حَرْف مَصْدَرِيّ لِرِعايَةِ المَعْنى لا مانِع مِنهُ ﴿إنّ فِي ذَلِكَ لَآيات﴾ لَعِبَرًا ﴿لِأُولِي النُّهى﴾ لِذَوِي العُقُول"],[129,129,"﴿ولَوْلا كَلِمَة سَبَقَتْ مِن رَبّك﴾ بِتَأْخِيرِ العَذاب عَنْهُمْ إلى الآخِرَة ﴿لَكانَ﴾ الإهْلاك ﴿لِزامًا﴾ لازِمًا لَهُمْ فِي الدُّنْيا ﴿وأَجَل مُسَمًّى﴾ مَضْرُوب لَهُمْ مَعْطُوف عَلى الضَّمِير المُسْتَتِر فِي كانَ وقامَ الفَصْل بِخَبَرِها مَكان التَّأْكِيد"],[130,130,"﴿فاصْبِرْ عَلى ما يَقُولُونَ﴾ مَنسُوخ بِآيَةِ القِتال ﴿وسَبِّحْ﴾ صَلِّ ﴿بِحَمْدِ رَبّك﴾ حال: أيْ مُلْتَبِسًا بِهِ ﴿قَبْل طُلُوع الشَّمْس﴾ صَلاة الصُّبْح ﴿وقَبْل غُرُوبها﴾ صَلاة العَصْر ﴿ومِن آناء اللَّيْل﴾ ساعاته ﴿فَسَبِّحْ﴾ صَلِّ المَغْرِب والعِشاء ﴿وأَطْراف النَّهار﴾ عَطْف عَلى مَحَلّ مِن آناء المَنصُوب: أيْ صَلِّ الظُّهْر لِأَنَّ وقْتها يَدْخُل بِزَوالِ الشَّمْس فَهُوَ طَرَف النِّصْف الأَوَّل وطَرَف النِّصْف الثّانِي ﴿لَعَلَّك تَرْضى﴾ بِما تُعْطى مِن الثَّواب"],[131,131,"﴿ولا تَمُدَّنَّ عَيْنَيْك إلى ما مَتَّعْنا بِهِ أزْواجًا﴾ أصْنافًا ﴿مِنهُمْ زَهْرَة الحَياة الدُّنْيا﴾ زِينَتها وبَهْجَتها ﴿لِنَفْتِنهُمْ فِيهِ﴾ بِأَنْ يَطْغَوْا ﴿ورِزْق رَبّك﴾ فِي الجَنَّة ﴿خَيْر﴾ مِمّا أُوتُوهُ فِي الدُّنْيا ﴿وأَبْقى﴾ أدْوَم"],[132,132,"﴿وأْمُرْ أهْلك بِالصَّلاةِ واصْطَبِرْ﴾ اصْبِرْ ﴿عَلَيْها لا نَسْأَلك﴾ نُكَلِّفك ﴿رِزْقًا﴾ لِنَفْسِك ولا لِغَيْرِك ﴿نَحْنُ نَرْزُقك والعاقِبَة﴾ الجَنَّة ﴿لِلتَّقْوى﴾ لِأَهْلِها"],[133,133,"﴿وقالُوا﴾ المُشْرِكُونَ ﴿لَوْلا﴾ هَلّا ﴿يَأْتِينا﴾ مُحَمَّد ﴿بِآيَةٍ مِن رَبّه﴾ مِمّا يَقْتَرِحُونَهُ ﴿أوَلَمْ تَأْتِهِمْ﴾ بِالتّاءِ والياء ﴿بَيِّنَة﴾ بَيان ﴿ما فِي الصُّحُف الأُولى﴾ المُشْتَمِل عَلَيْهِ القُرْآن مِن أنْباء الأُمَم الماضِيَة وإهْلاكهمْ بِتَكْذِيبِ الرُّسُل"],[134,134,"﴿ولَوْ أنّا أهْلَكْناهُمْ بِعَذابٍ مِن قَبْله﴾ قَبْل مُحَمَّد الرَّسُول ﴿لَقالُوا﴾ يَوْم القِيامَة ﴿رَبّنا لَوْلا﴾ هَلّا ﴿أرْسَلْت إلَيْنا رَسُولًا فَنَتَّبِع آياتك﴾ المُرْسَل بِها ﴿مِن قَبْل أنْ نَذِلّ﴾ فِي القِيامَة ﴿ونَخْزى﴾ فِي جَهَنَّم"],[135,135,"﴿قُلْ﴾ لَهُمْ ﴿كُلّ﴾ مِنّا ومِنكُمْ ﴿مُتَرَبِّص﴾ مُنْتَظِر ما يَئُول إلَيْهِ الأَمْر ﴿فَتَرَبَّصُوا فَسَتَعْلَمُونَ﴾ فِي القِيامَة ﴿مَن أصْحاب الصِّراط﴾ الطَّرِيق ﴿السَّوِيّ﴾ المُسْتَقِيم ﴿ومَن اهْتَدى﴾ مِن الضَّلالَة أنَحْنُ أمْ أنْتُمْ"]]};
